package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalGroupedRounds.*;
import org.kanger.ContextUniversalGroupedRounds.Result;
import org.kanger.ContextUniversalGroupedChainAudit.*;
import org.kanger.ContextUniversalCompoundExchange.Exchange;
import org.kanger.ContextWitnessResultTransport.*;

/** Independent whole stable-chain replay and actual cross-round identity forgery controls. */
public final class ContextUniversalGroupedChainAuditRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static final class Fixture {
        final Snapshot x,a,b;final List<Snapshot> foreign;final Packet input;final Map<Cut,PrivatePool> pools;
        final Exchange compounds;final ContextUniversalSignedUnitExchange.Exchange units;
        final ContextUniversalFrozenBranch.Limits limits=ContextUniversalGroupedRoundsRunner.limits(16);
        final ContextUniversalGroupedLocalRounds.Limits local=ContextUniversalGroupedRoundsRunner.local();final Result trace;
        Fixture(boolean symbolic,boolean privateParameter)throws Exception {
            x=ContextUniversalGroupedRoundsRunner.bind(true,privateParameter?"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);":"!anchor(1); !@u p(u);");
            a=ContextUniversalGroupedRoundsRunner.bind(false,privateParameter?"!$u a(u,1)&&hidden(u,1);":symbolic?"!@u @v p(u)&&b(u)->~r(u,v);":"!@u p(u)&&b(u)&&c(u)->r(u);");
            b=ContextUniversalGroupedRoundsRunner.bind(false,privateParameter?"!@u b(u,2);":"!b(1);");foreign=Arrays.asList(a,b);input=ContextPrivateWitnessPoolRunner.common(x);
            if(privateParameter){PrivatePool p=ContextWitnessResultTransport.privatePool(input,x,a,WORK);pools=Collections.singletonMap(p.cut,p);}else pools=Collections.emptyMap();
            compounds=ContextUniversalGroupedRoundsRunner.exchange(x,foreign,input,pools);units=ContextUniversalGroupedRoundsRunner.units(compounds);trace=ContextUniversalGroupedRounds.run(x,foreign,input,pools,units,compounds,limits,local,8,WORK);require(trace.status==Status.STABLE_GROUPED_POOLS,trace.phase+": "+trace.reason);
        }
        Inspection audit(Result r,int work){return ContextUniversalGroupedChainAudit.inspect(x,foreign,input,pools,units,compounds,limits,local,8,r,work);}
    }
    static Receipt yes(Inspection i){require(i.audited&&i.output!=null,i.phase+": "+i.reason);return i.output;}
    static void no(Inspection i,String why){require(!i.audited&&i.output==null,why+": "+i.phase+" "+i.reason);}
    static void mutate(Fixture f,Object owner,String field,Object value,String why)throws Exception {java.lang.reflect.Field v=owner.getClass().getDeclaredField(field);v.setAccessible(true);Object old=v.get(owner);v.set(owner,value);try{no(f.audit(f.trace,WORK),why);}finally{v.set(owner,old);}}
    static void chain()throws Exception {
        Fixture f=new Fixture(false,false);Receipt receipt=yes(f.audit(f.trace,WORK));require(receipt.trace==f.trace&&receipt.input==f.input&&receipt.compounds==f.compounds,"actual stable trace/input bound to receipt");require(f.trace.history.get(0).compoundChanged&&!f.trace.history.get(0).commonChanged,"independent replay includes compound-only progress");ContextUniversalGroupedChainAudit.check(receipt,WORK);++checks;
        no(f.audit(f.trace,1),"audit work exhaustion has no successful receipt");Round first=f.trace.history.get(0),last=f.trace.history.get(f.trace.history.size()-1);
        mutate(f,first,"number",2,"actual round ordering");mutate(f,last,"input",first.input,"equal-content old Packet cannot replace actual next barrier");mutate(f,f.trace,"completedRounds",f.trace.completedRounds+1,"complete round count");mutate(f,f.trace,"output",first.barrier,"terminal output cannot point to earlier barrier");mutate(f,first,"compoundChanged",false,"compound-only progress cannot masquerade as unchanged");mutate(f,last,"compoundChanged",true,"terminal stability flags independently required");mutate(f,first,"symbolicChanged",true,"nonterminal change flags recomputed from typed inventories, not trusted");
        mutate(f,last,"symbolicInput",first.symbolicInput,"authentic stale unit carrier");mutate(f,last,"compoundInput",first.compoundInput,"authentic stale compound carrier");
        Map<Cut,ContextUniversalGroupedLocalRounds.Certificate> missing=new LinkedHashMap<>(first.certificates);missing.remove(Cut.of(f.b));mutate(f,first,"certificates",missing,"missing stable cut certificate");Map<Cut,ContextUniversalSignedProductAudit.Result> products=new LinkedHashMap<>(first.products);products.put(Cut.of(f.b),first.products.get(Cut.of(f.a)));mutate(f,first,"products",products,"authentic product audit from another cut");
        mutate(f,last.compoundOutput,"barrier",first.barrier,"equal-content older fixed barrier cannot rebase current carrier");mutate(f,last.barrier,"localChanged",true,"merged local change flag independently required");mutate(f,f.trace,"history",Collections.singletonList(last),"missing actual prior round");
        Map<Cut,ContextUniversalFrozenConstraints.Result> wrong=new LinkedHashMap<>(last.compoundOutput.checks);wrong.put(Cut.of(f.b),first.checks.get(Cut.of(f.b)));mutate(f,last.compoundOutput,"checks",wrong,"same cut stale check cannot donate final compound inventory");
        ContextUniversalSignedProductAudit.Result p=first.products.get(Cut.of(f.b));mutate(f,p,"products",Collections.emptyList(),"product obligations independently reconstructed, not just bound flag");
        no(ContextUniversalGroupedChainAudit.inspect(f.x,Collections.singletonList(f.a),f.input,f.pools,f.units,f.compounds,f.limits,f.local,8,f.trace,WORK),"initial exact supplied cut inventory");no(ContextUniversalGroupedChainAudit.inspect(f.x,f.foreign,f.input,f.pools,f.units,f.compounds,f.limits,ContextUniversalGroupedRoundsRunner.local(),8,f.trace,WORK),"actual local invocation policy");
        Result limited=ContextUniversalGroupedRounds.run(f.x,f.foreign,f.input,f.pools,f.units,f.compounds,f.limits,f.local,1,WORK);require(limited.status==Status.INCOMPLETE&&limited.history.isEmpty(),"actual discarded incomplete prefix");no(f.audit(limited,WORK),"incomplete prefix cannot be certified stable");
        require(receipt.foreign.size()==2&&receipt.pools.isEmpty(),"sealed original caller frame");boolean immutable=false;try{receipt.foreign.clear();}catch(UnsupportedOperationException e){immutable=true;}require(immutable,"immutable supplied snapshot list");
    }
    static void privateCase()throws Exception {Fixture f=new Fixture(false,true);Receipt r=yes(f.audit(f.trace,WORK));require(f.trace.output.packet.items.stream().anyMatch(i->i.atom.predicate.equals("r"))&&f.trace.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("a")||i.atom.predicate.equals("hidden")),"independent private rebase replay certifies only X-dependent Origin products");require(r.trace.output.privatePools.get(Cut.of(f.a)).common==f.trace.output.packet,"actual final private/common binding");mutate(f,r.trace.output.privatePools.get(Cut.of(f.a)),"common",f.input,"independent final private rebase frame");PrivatePool result=f.trace.output.privatePools.get(Cut.of(f.a)),branch=f.trace.output.branches.get(Cut.of(f.a)).privateAfter;java.lang.reflect.Field field=PrivatePool.class.getDeclaredField("sources");field.setAccessible(true);Object rs=field.get(result),bs=field.get(branch);field.set(result,Collections.emptySet());field.set(branch,Collections.emptySet());try{no(f.audit(f.trace,WORK),"jointly forged branch/final Source inventories must be anchored to original native pool");}finally{field.set(result,rs);field.set(branch,bs);}PrivatePool original=f.pools.get(Cut.of(f.a));mutate(f,original,"sources",Collections.emptySet(),"initial private Source inventory authenticated against actual snapshot");Set<PrivatePool> all=Collections.newSetFromMap(new IdentityHashMap<PrivatePool,Boolean>());all.add(original);for(Round round:f.trace.history){all.addAll(round.privateInput.values());all.addAll(round.barrier.privatePools.values());for(ConstraintTransfer t:round.barrier.branches.values())if(t.privateAfter!=null)all.add(t.privateAfter);}Map<PrivatePool,Object> inventory=new IdentityHashMap<>();for(PrivatePool p:all){inventory.put(p,field.get(p));field.set(p,Collections.emptySet());}try{Inspection forged=f.audit(f.trace,WORK);no(forged,"mutually consistent forged private Sources cannot replace native anchoring");require(forged.phase.equals("initial-frame"),"coherent forged inventory reaches independent native-frame authentication");}finally{for(Map.Entry<PrivatePool,Object> entry:inventory.entrySet())field.set(entry.getKey(),entry.getValue());}java.lang.reflect.Field ds=PrivatePool.class.getDeclaredField("declarations");ds.setAccessible(true);Object rd=ds.get(result),bd=ds.get(branch);ds.set(result,Collections.emptyList());ds.set(branch,Collections.emptyList());try{no(f.audit(f.trace,WORK),"jointly forged declaration inventory retains actual physical native manifest obligation");}finally{ds.set(result,rd);ds.set(branch,bd);}}
    static void symbolicAndRefutation()throws Exception {
        Fixture f=new Fixture(true,false);yes(f.audit(f.trace,WORK));require(f.trace.history.get(0).symbolicChanged&&!f.trace.history.get(0).commonChanged,"symbolic-only production requires independently replayed next barrier");
        Snapshot opposite=ContextUniversalGroupedRoundsRunner.bind(false,"!b(1); !r(1,987654);");List<Snapshot> cuts=Arrays.asList(f.a,opposite);Exchange e=ContextUniversalGroupedRoundsRunner.exchange(f.x,cuts,f.input,Collections.emptyMap());ContextUniversalSignedUnitExchange.Exchange units=ContextUniversalGroupedRoundsRunner.units(e);Result refused=ContextUniversalGroupedRounds.run(f.x,cuts,f.input,Collections.emptyMap(),units,e,f.limits,f.local,8,WORK);require(refused.status==Status.REFUTED&&refused.history.isEmpty(),"actual refuted compound continuation, not finite domain sampling");no(ContextUniversalGroupedChainAudit.inspect(f.x,cuts,f.input,Collections.emptyMap(),units,e,f.limits,f.local,8,refused,WORK),"refutation evidence cannot be relabelled a stable-chain receipt");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("grouped-chain-audit-").toString());chain();symbolicAndRefutation();System.out.println("CONTEXT_UNIVERSAL_GROUPED_CHAIN_AUDIT_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
